python3 - <<'EOF'
import unicodedata
text=open('/tmp/probe_h2/out.txt',encoding='utf-8').read()
def dispw(s):
    w=0
    for ch in s:
        if unicodedata.category(ch)=='Cc':  # control
            w+=0
        else:
            w+= 2 if unicodedata.east_asian_width(ch) in 'WF' else 1
    return w
for i,l in enumerate(text.split('\n')):
    if not l or l[0]=='≖':
        if l: print(i,'BORDER',len(l))
        continue
    cells=l.split('⋮')[1:-1]
    print(i,[ (repr(c), len(c)) for c in cells ])
EOF
